version.content:
pipeline {
    agent any
    options {
        // 配置构建保留策略
        buildDiscarder(logRotator(
            numToKeepStr: '10',        // 最多保留 10 个构建[reference:11]
            // daysToKeepStr: '10',       // 保留 10 天内的构建[reference:12]
            artifactNumToKeepStr: '10', // 最多保留 10 个构建的制品[reference:13]
            // artifactDaysToKeepStr: '5' // 保留 5 天内的构建制品[reference:14]
        ))
    }
    parameters {
        choice(
            name: 'OPERATION',
            choices: ['deploy', 'rollback', 'start', 'stop', 'restart'],
            description: '操作类型：部署/回滚/启动/停止/重启'
        )
        string(name: 'ENV', defaultValue: 'PROD', description: '环境：DEV/TEST/UAT/PRE/PROD')
        string(name: 'APP_NAME', defaultValue: 'change-management-frontend', description: '应用名称')
        string(name: 'VERSION',description: '镜像标签（不填写时按照脚本规则）')
        string(name: 'ROLLBACK_TAG', defaultValue: '', description: '回滚标签（回滚时优先使用）')
        string(name: 'Branch', defaultValue: 'dev', description: '分支名称')
    }

    environment {
        // 镜像仓库配置
        DOCKER_REGISTRY = 'harbor.bigdata.com:12021'
        DOCKER_IMAGE_PREFIX = "${DOCKER_REGISTRY}/devops"

        // Git 配置 http://220.163.62.194:12001/huangmeng/bigkingsendmsg.git
        GIT_URL ="${GIALAB_ADDRESS}/front/science-achievement-change-management.git"

        // AWX 配置（仅部署时触发）
        AWX_URL = 'http://20.12.18.199:8013'
        AWX_WEBHOOK_TOKEN = 'IhDJxIyQvZKaawrdSoDV'
        AWX_JT_ID = '24' //ansible-awx 模版ID
        TARGET_HOST = '20.31.130.112'
        COMPOSE_PATH = '/data/change-management-frontend'

        // 凭据 ID（需要在 Jenkins 中配置）
        HARBOR_CREDENTIALS_ID = 'harbor-credential-id'  // Harbor 用户名密码
        MINIO_CREDS = 'c44a58e0-b640-471c-ab76-a667bb5e4fcb'  // 使用在 Jenkins 中配置的凭据ID
        ARTIFACT_BUCKET = 'deploy'   // 定义统一使用的存储桶名称
        //业务健康检查
        health_port = '8082'
        health_path = '/'
    }

    stages {
        stage('参数校验') {
            steps {
                script {
                    echo "========================================"
                    echo " Pipeline 执行参数"
                    echo "========================================"
                    echo "操作类型: ${params.OPERATION}"
                    echo "应用名称: ${params.APP_NAME}"
                    echo "环境: ${params.ENV}"
                    echo "版本号: ${params.VERSION ?: 'N/A'}"
                    echo "回滚标签: ${params.ROLLBACK_TAG ?: 'N/A'}"
                    echo "远程路径: ${env.REMOTE_PATH}"
                    echo "========================================"

                    // if (params.OPERATION == 'deploy') {
                    //     error("部署操作必须指定 deploy 参数!")
                    // }
                    // if (params.OPERATION == 'rollback' && !params.ROLLBACK_TAG && !params.VERSION) {
                    //     error("回滚操作必须指定 ROLLBACK_TAG 或 VERSION 参数!")
                    // }
                }
            }
        }
        stage('Show Version') {
            steps {
                // 获取当前构建的唯一数字编号，例如：123
                echo "构建编号是：${env.BUILD_NUMBER}"
                // 获取格式化的构建标签，例如：jenkins-my-app-123
                echo "构建标签是：${env.BUILD_TAG}"
                // 获取用于命名制品的组合ID，例如：123
                echo "构建ID是：${env.BUILD_ID}"
                // 获取任务名称，例如：my-pipeline-job
                echo "任务名称是：${env.JOB_NAME}"
                sh 'printenv'
            }
        }

        stage('代码检出') {
            when { expression { params.OPERATION == 'deploy' } }
            steps {
                echo "Checking out code from branch: ${params.Branch}"
                checkout scmGit(
                    branches: [[name: "${params.Branch}"]],
                    extensions: [],
                    userRemoteConfigs: [[
                        credentialsId: 'SSH-KEY-FOR-GITLAB',
                        url: "${GIT_URL}"
                    ]]
                )
                script {
                    // 获取当前 commit ID，用于生成镜像标签
                    sh 'git rev-parse --short HEAD > GIT_COMMIT_SHORT'
                    def gitCommit = readFile('GIT_COMMIT_SHORT').trim()
                    env.GIT_COMMIT_SHORT = gitCommit
                    echo "代码检出完成，Commit: ${env.GIT_COMMIT_SHORT}"
                }
            }
        }
        stage('Dependencies Install') {
            steps {
                sh 'node -v'
                sh 'pnpm -v'
                sh 'pnpm install --frozen-lockfile -registry=https://registry.npmmirror.com' // 推荐生产环境使用 --frozen-lockfile
            }
        }
        stage('pnpm前端构建') {
            when { expression { params.OPERATION == 'deploy' } }
            steps {
                script {
                    echo "开始 pnpm 构建..."
                    sh '''
                    pnpm run build
                '''
                    echo "pnpm前端构建完成"
                }
            }
        }
    stage('Docker 构建与推送') {
        when { expression { params.OPERATION == 'deploy' } 
    }
    steps {
        script {
            def imageTag = params.VERSION ?: "build-${BUILD_NUMBER}-${env.GIT_COMMIT_SHORT}"
            env.LATEST_IMAGE_TAG = imageTag  // 提前赋值，供后续使用
            def fullImageName = "${env.DOCKER_IMAGE_PREFIX}/${params.APP_NAME}:${imageTag}"
            echo "构建镜像: ${fullImageName}"
        }

        // 登录 Docker 仓库（使用标准 withCredentials 语法）
        withCredentials([
            usernamePassword(
                credentialsId: env.HARBOR_CREDENTIALS_ID,
                usernameVariable: 'HARBOR_USER',
                passwordVariable: 'HARBOR_PASS'
            )
        ]) {
            sh """
                docker login ${env.DOCKER_REGISTRY} -u \${HARBOR_USER} -p \${HARBOR_PASS}
            """
        }

        script {
            def fullImageName = "${env.DOCKER_IMAGE_PREFIX}/${params.APP_NAME}:${env.LATEST_IMAGE_TAG}"
            // 如果 Dockerfile 在子目录 bigdata-sendmsg 中，取消注释 dir 块
            // dir('bigdata-sendmsg') {
            sh """
                docker build  -t ${fullImageName} -f Dockerfile .
                docker push ${fullImageName}
            """
            // }
            writeFile file: "${WORKSPACE}/.image_tag", text: env.LATEST_IMAGE_TAG
            echo "镜像推送完成: ${fullImageName}"
        }
    }
}

        stage('触发 AWX 部署') {
            when { expression { params.OPERATION == 'deploy' } }
            steps {
                script {
                    def payload = """{
                        "event_type": "deploy",
                        "ref": "${env.GIT_BRANCH}",
                        "image": {
                            "registry": "${DOCKER_REGISTRY}",
                            "project": "devops",
                            "name": "${params.APP_NAME}",
                            "tag": "${env.LATEST_IMAGE_TAG}",
                            "full": "${env.DOCKER_IMAGE_PREFIX}/${params.APP_NAME}:${env.LATEST_IMAGE_TAG}"
                        },
                        "target": {
                            "host": "${TARGET_HOST}",
                            "compose_path": "${COMPOSE_PATH}",
                            "service": "${params.APP_NAME}",
                            "build_id": "${env.BUILD_ID}",
                            "health_port": "${health_port}",
                            "health_path": "${health_path}",
                            "artifact_url": "http://20.12.18.199:8013/artifacts/${ARTIFACT_BUCKET}/releases/${env.JOB_NAME}/${env.BUILD_NUMBER}/xx.jar",
                            "artifact_name": "bigdata-sendmsg-0.0.1-SNAPSHOT.jar",
                            "bucket_name":"${ARTIFACT_BUCKET}",
                            "object_key":"/releases/${env.JOB_NAME}/${env.BUILD_NUMBER}/sendMsg-0.0.1-SNAPSHOT.jar",
                            "app_env_vars": {"NACOS_SERVER": "39.129.77.191:9000"},
                            "java_proxy_host":"172.17.44.8",
                            "java_proxy_port":"7897"
                        }
                    }"""
                    sh """
                        curl -s -X POST \
                            -H "Content-Type: application/json" \
                            -H "X-Custom-Webhook-Token: ${AWX_WEBHOOK_TOKEN}" \
                            -d '${payload}' \
                            ${AWX_URL}/api/v2/job_templates/${AWX_JT_ID}/custom/
                    """
                    echo "AWX 触发完成（异步）"
                }
            }
        }
    }

    post {
        always {
            echo '========================================'
            echo " Pipeline 执行完成 - 操作: ${params.OPERATION}"
            echo " 最终状态: ${currentBuild.result ?: 'SUCCESS'}"
            echo '========================================'
        }
        success {
            echo "✅ ${params.OPERATION} 操作成功完成!"
        }
        failure {
            echo "❌ ${params.OPERATION} 操作失败，请检查日志!"
        }
    }
}
